struct Camera {
    float focal_length;
    vec3 right;
    vec3 up;
    vec3 forward;
};

struct Ray {
    vec3 origin;
    vec3 direction;
};

struct Material {
    bool reflexive;
    vec3 color;
};

struct Hit {
    Material material;
    vec3 position;
    vec3 normal;
    float dist;
    bool has_hit;
};

struct PointLight {
    float intensity;
    vec3 direction;
};

struct Sphere {
    vec3 center;
    float radius;
    Material material;
};

struct Triangle {
    vec3 v0;
    vec3 v1;
    vec3 v2;
    Material material;
};

Hit get_hit_sphere(Sphere sphere, Ray ray)
{
    vec3 s_delta = ray.origin - sphere.center;

    float a = dot(ray.direction, ray.direction);
    float b = 2. * dot(s_delta, ray.direction);
    float c = dot(s_delta, s_delta) - (sphere.radius * sphere.radius);

    float delta = b*b - 4. * a * c;

    if (delta > 0.) {
        float sqrt_delta = sqrt(delta);
        float rho = 1. / (2.*a);
        float s1 = (sqrt_delta - b) * rho;
        float s2 = -(sqrt_delta + b) * rho;

        if (s1 > 0. || s2 > 0.) {
            Hit hit;

            hit.has_hit = true;

            hit.dist = (s1 > 0. && s1 < s2) ? s1 : s2;
            hit.position = ray.origin + ray.direction * hit.dist;
            hit.normal = normalize(hit.position - sphere.center);

            hit.material = sphere.material;

            return hit;
        }
    }

    Hit hit;
    hit.has_hit = false;

    return hit;
}

Hit get_hit_triangle(Triangle triangle, Ray ray)
{
    vec3 v1v0 = triangle.v1 - triangle.v0;
    vec3 v2v0 = triangle.v2 - triangle.v0;
    vec3 rov0 = ray.origin - triangle.v0;
    vec3  n = cross(v1v0, v2v0);
    vec3  q = cross(rov0, ray.direction);
    float d = 1. / dot(ray.direction, n);
    float u = d * dot(-q, v2v0);
    float v = d * dot( q, v1v0);
    float t = d * dot(-n, rov0);

    if(u<0.0 || v<0.0 || (u+v)>1.0) t = -1.0;

    return Hit(triangle.material, vec3(t, u, v), vec3(1., 1., 1.), length(vec3(t, u, v) - ray.origin), false);
}

Sphere sphere_1 = Sphere(vec3(0., -3., 10.), 2., Material(true, vec3(1., 0., 0.)));
Sphere sphere_2 = Sphere(vec3(0., -3., 10.), 5., Material(true, vec3(0., 0., 1.)));

Triangle triangle_1 = Triangle(vec3(0., -3., 15.), vec3(0., -5., 15.), vec3(0., -3., 10.), Material(false, vec3(1., 0., 0.)));

Hit get_closest(Ray ray)
{
    Hit closest_hit = get_hit_sphere(sphere_1, ray);

    Hit hit_1 = get_hit_sphere(sphere_2, ray);

    Hit hit_2 = get_hit_triangle(triangle_1, ray);

    if (hit_1.has_hit && (!closest_hit.has_hit || hit_1.dist < closest_hit.dist)) closest_hit = hit_1;

    if (hit_2.has_hit && (!closest_hit.has_hit || hit_2.dist < closest_hit.dist)) closest_hit = hit_2;


    return closest_hit;
}


Ray get_ray(Camera cam, vec2 coords)
{
    Ray r;

    //r.origin = vec3(0., 0., 0.);
    r.direction  = cam.forward * cam.focal_length;
    r.direction += cam.right   * coords.x;
    r.direction += cam.up      * coords.y;
    r.direction  = normalize(r.direction);

    return r;
}

PointLight sun = PointLight(.5, normalize(vec3(0., 1., 0.)));

Camera camera = Camera(1., vec3(1., 0., 0.), vec3(0., 1., 0.), vec3(0., 0., 1.));

float intensity;
float sun_factor;

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    //sun.direction.x = cos(iTime);
    //sun.direction.y = sin(iTime);
    //sun.direction = normalize(sun.direction);

    sphere_2.center.x = -cos(iTime) * 15.;
    sphere_2.center.y = -sin(iTime) * 15.;

    sphere_1.material.color.x = sin(iTime);
    sphere_1.material.color.y = cos(iTime*0.5);
    sphere_1.material.color.z = tan(iTime);

    // Rendering
    vec2 uv = (fragCoord * 2. - iResolution.xy) / iResolution.y;

    Ray ray = get_ray(camera, uv.xy);

    Hit hit = get_closest(ray);

    if (hit.has_hit) {
        intensity = 0.4;
        sun_factor = dot(-sun.direction, hit.normal);

        if (sun_factor > 0.) {
            Hit light_check = get_closest(Ray(hit.position + hit.normal * 0.01, -sun.direction));
            if (!light_check.has_hit) intensity += sun.intensity * sun_factor;
        }

        fragColor = vec4(hit.material.color * intensity, 1.);
    } else
        fragColor = vec4(0., 0., 0., 1.0);
}
